// DocVault-AI M6: Create dummy manifest JSON with routing & naming
// 
// UMLAUT POLICY (M6):
// - Safe filenames: ASCII only (Anhoerung, Buergergeld, Pfaendung)
// - Display titles: Umlauts allowed (Anhörung, Bürgergeld)
// - Evidence quotes: Original OCR umlauts preserved unchanged
// - JSON encoding: UTF-8 with ensure_ascii=False
// - Paperless tags: ASCII-stable (doc_type:anhoerung)
// - No real documents, no secrets, no paperless upload

const config = $input.first().json;
const checksumLine = $items('SSH: Compute SHA256 (placeholder)')[0]?.json?.stdout || '';
const sha256 = checksumLine.split(/\s+/)[0] || 'M6_DUMMY_HASH_NOT_COMPUTED';

const manifest = {
  manifest_version: '1.0',
  docvault_id: 'M6-DUMMY-' + Date.now(),
  source: {
    method: 'dummy',
    scanner_model: null,
    original_filename: 'test.txt',
    file_sha256: sha256,
    file_size_bytes: 88,
    content_type: 'text/plain'
  },
  processing: {
    ocr_engine: 'tesseract_local',
    ocr_confidence_avg: null,
    page_count: 1,
    text_length: 88,
    language_detected: 'de',
    processing_timestamp: new Date().toISOString()
  },
  classification: {
    document_type: 'Dummy',
    sender: 'DocVault M6 Test Suite',
    date_on_document: new Date().toISOString().split('T')[0],
    has_deadline: false,
    deadline_date: null,
    is_official_letter: false,
    contains_legal_remedy_instruction: false,
    contains_payment_demand: false,
    is_hearing: false,
    case_category: 'Unbekannt',
    keywords: ['dummy', 'm6', 'docvault', 'test'],
    llm_model: null,
    llm_confidence: null
  },
  risk_class: 'GREEN_SAFE',
  review: {
    status: 'PENDING',
    assigned_to: null,
    reviewed_at: null,
    reviewer_notes: null
  },
  evidence: {
