    pipeline_version: '0.6.0-m6',
    processing_host: 'ct107',
    raw_ocr_valid: true,
    llm_response_valid: false,
    manual_override: false,
    notes: [
      'M6 Dummy Workflow — No real documents, no paperless upload',
      'Naming: ASCII-stable filenames, umlauts in display titles',
      'JSON: UTF-8 encoding, ensure_ascii=False'
    ]
  },
  paperless: {
    paperless_document_id: null,
    paperless_upload_task_id: null,
    upload_status: 'not_uploaded',
    uploaded_at: null,
    custom_fields: {
      paperless_mode: 'dryrun',
      upload_attempted: false
