    deterministic_document_type: 'Unbekannt',
    llm_domain: null,
    llm_document_type: null,
    final_domain: 'Unbekannt',
    final_document_type: 'Unbekannt',
    // M6: display fields with umlauts for human readability
    display_domain: 'Unbekannt',
    display_document_type: 'Unbekannt',
    confidence: 0.0,
    matched_domain_keywords: ['dummy'],
    matched_type_keywords: ['dummy'],
    has_risk_terms: false,
    risk_terms_found: [],
    notes: ['M6 Dummy Routing']
  },
  naming_detail: {
    // M6: safe_filename is ASCII-stable — NO umlauts
    safe_filename: 'unknown-date__Unbekannt__Unbekannt__Unbekannt__sha256-000000000000.pdf',
    sha256_suffix: '000000000000',
    sanitizer_version: 'naming-v1',
    // M6: display_title may contain umlauts for human readability
    display_title: 'Unbekannt'
