    target_policy: 'tests',
    move_allowed: false,
    requires_human_review: true,
    evidence: []
  },
  created_at: new Date().toISOString(),
  updated_at: new Date().toISOString()
};
return [{ json: { manifest_json: JSON.stringify(manifest, null, 2) } }];

// M6 Final Summary: Compile evidence report with umlaut policy check
const items = $input.all();
const summary = {
  workflow: 'DocVault-AI M6 Intake (Dummy)',
  status: 'completed',
  real_documents_allowed: false,
  paperless_mode: 'dryrun',
  ollama_used: false,
  manifest_created: true,
  manifest_written_to: '/srv/docvault/tests/dummy-output/m6_dummy_manifest.json',
  files_processed: items.length,
  risk_class: 'GREEN_SAFE',
  umlaut_policy: {
    enforced: true,
    filenames_ascii_only: true,
    display_titles_umlauts: true,
    json_utf8: true
  },
  timestamp: new Date().toISOString(),
  notes: [
    'M6 Dummy Workflow completed.',
    'No real documents, no paperless upload, no Ollama LAN.',
